    background-color: #2d3035 !important;
}

/* Убрать любые белые фоны */
[style*="background-color: white"],
[style*="background-color:#fff"],
[style*="background-color:#ffffff"],
[style*="background: white"],
[style*="background:#fff"],
[style*="background:#ffffff"] {
    background-color: #2d3035 !important;
    background-image: none !important;
}

/* Исправить ячейки с классами состояний */
td.category, 
td.bug-category,
td.status,
td.priority {
    background-color: #2d3035 !important;
}

/* Для пустых ячеек с белым фоном */
td:empty,
td[style=""],
td[style=" "] {
    background-color: #2d3035 !important;
}

/* Атомарные стили для максимальной специфичности */
html body .widget-body .table-bordered > tbody > tr > td,
html body .widget-body .table > tbody > tr > td,
html body .main-container .table-bordered > tbody > tr > td {
    background-color: #2d3035 !important;
    color: #e6e6e6 !important;
}
